from pathlib import Path
import json
H=Path(__file__).resolve().parent; R=H.parents[3]; P=H.parent/'2026-09-19-review-comparison'; prefix=H.relative_to(R).as_posix(); M='QFEP_Sandbox'
def para(start,old=False):
 p=(H/'before' if old else R)/'commons/maps'/M/'final.md'
 return next(t for t in p.read_text(encoding='utf-8').split('\n\n') if t.startswith(start))
d=json.loads((P/'qfeplaboratory.json').read_text(encoding='utf-8'))
old=json.loads((H/'before/doc/book/iterations/2026-09-19-review-comparison/qfeplaboratory.json').read_text(encoding='utf-8'))
assert d['items'][:len(old['items'])]==old['items'], 'Earlier review cards must remain intact'
checks=json.loads((H/'content-checks.json').read_text(encoding='utf-8'))
assert checks['passed']
r=json.loads((H/(M+'-runtime.json')).read_text(encoding='utf-8'))
assert r['passed'] and len(r['checks'])==26
d['status']='Seven laboratory halls reviewed; Sandbox restored to museum and book; Synthesis next'
d['summary']='QFEP asks who may revise the terms. The laboratory moves through arrangements, prediction, possible branches, recommendations, signed change and numerical resolution. Sandbox now lets the visitor make and interrupt one actual connection: the handles move, the receiver may follow, and a cut leaves the last accepted values behind. The surrounding particle field remains independent. All eight halls are restored to the authored route; Synthesis remains the final encounter/manuscript pass.'
cards=[
 dict(title='Sandbox: a value reaches another body',description='The existing Lambda and Phi handles now connect to the existing reactor through a visible, switchable route. Before connection, local feedback and received values disagree. CONNECT / CUT makes the difference available to the visitor instead of leaving the manuscript to describe a missing feature.',images=[prefix+'/sandbox-cut.png',prefix+'/sandbox-connected.png'],captions=['CUT: handles offer lambda 0.85 and phi +0.70; the reactor still uses 0.40 and 0.00.','CONNECTED: unchanged handles now reach the reactor; it uses 0.85 and +0.70.'],image_note='Actual Godot views from the same camera. The receiver changes colour, pulse and particle launch speed according to its authored mapping. These are not measured entropy, freedom or biological life. The nearby green particle field is a separate process.',text_kind='book — turn a missing relationship into an encounter',before=para('The intended sandbox',True),after=para('Repeat one handle movement')+'\n\n'+para('Press CONNECT'),report=prefix+'/final.diff',report_label='Exact Sandbox manuscript diff'),
 dict(title='Cut the route. Something still remains.',description='Cutting input delivery retains the last accepted values. Moving the handles back does not undo the reactor’s state. Reconnection accepts the present settings. REPEAT gives a common animation start without resetting those values or taking command of the rest of the room.',images=[prefix+'/sandbox-held.png',prefix+'/sandbox-reconnected.png'],captions=['After cutting: handles move to 0.15 / -0.70; receiver retains 0.85 / +0.70.','Reconnect: the same handle positions now deliver 0.15 / -0.70 to the receiver.'],image_note='26 interaction/state checks pass, including real slider/button callbacks, repeated CPU pulse and jitter, cut/held input, immediate reconnection, independent field motion and rejection of missing or ambiguous local handles. GPU particle histories are not asserted identical.',text_kind='book — the critical question grows from what persists',before=para('A useful next experiment',True),after=para('Cut the route again')+'\n\n'+para('You can now make'),report=prefix+'/'+M+'-runtime.json',report_label='Interaction and walking evidence'),
 dict(title='An open laboratory, with something outside the connection',description='Sandbox existed on disk but had been omitted from authored museum routing and dropped from the book/trunk. It now stands between Edge of Chaos and Synthesis. The layers agree at 14 by 16; full-size handles and a compact console have clear approaches. All six placement families remain, and the reactor earns a third primary role.',images=[prefix+'/sandbox-controls.png',prefix+'/sandbox-gallery.png'],captions=['Offered and received values share a small console beside CONNECT / CUT and REPEAT.','Two handles, one receiver, an independent field and the retained formula inhabit the restored hall.'],image_note=f'Seven selected CharacterBody walking routes and {checks["count"]} content/preservation checks pass. Five authored works instantiate; legacy tt has no living scene. Six real museum images inspected. Earlier laboratory maps and manuscripts remain unchanged. Headset comfort, Quest performance and learner understanding still need testing.',text_kind='book — proximity is not a connection',before=para('Repeat one handle movement',True),after=para('Look toward the neighbouring'),report=prefix+'/SUMMARY.md',report_label='Decisions, restoration and limits')]
titles={c['title'] for c in cards}
d['items']=[i for i in d['items'] if i['title'] not in titles]+cards
(P/'qfeplaboratory.json').write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print('Published three Sandbox cards; earlier cards preserved')
